-- ---------------------------------------------------------------- pure logic (no Wireshark API; tested standalone)
local INT = {u8 = {1}, i8 = {1, true}, u16 = {2}, i16 = {2, true}, u32 = {4}, i32 = {4, true},
             u64 = {8}, i64 = {8}, f32 = {4}, char = {1}, byte = {1}}
local SPAN = {[1] = 256, [2] = 65536, [4] = 4294967296}

local function bxor(a, b)          -- no bit operators: Lua 5.2 (Wireshark <= 4.2) has none
  local r, bit = 0, 1
  while a > 0 or b > 0 do
    local x, y = a % 2, b % 2
    if x ~= y then r = r + bit end
    a, b, bit = (a - x) / 2, (b - y) / 2, bit * 2
  end
  return r
end

function F.decrypt(s, idx)         -- -> decrypted string, next index
  local out = {}
  for i = 1, #s do
    out[i] = string.char(bxor(s:byte(i), F.XOR[idx]))
    idx = idx >= 498 and 0 or idx + 1
  end
  return table.concat(out), idx
end

function F.pdu_len(byte_at)        -- byte_at(i) = i-th byte of the PDU -> total length, header length
  local b = byte_at(0)
  if b ~= 0 then return 1 + b, 1 end
  return 3 + byte_at(1) + 256 * byte_at(2), 3
end

-- conv = per-connection state {idx}; body = raw body (opcode + payload). -> XOR start index of a C->S body, or nil
function F.track(conv, c2s, body)
  if not c2s then
    if #body >= 4 and body:byte(1) == 0x07 and body:byte(2) == 0x08 then
      conv.idx = (body:byte(3) + 256 * body:byte(4)) % 499
    end
    return nil
  end
  local i = conv.idx
  if i then conv.idx = (i + #body) % 499 end
  return i
end

local function hex(s) return (s:gsub(".", function(c) return string.format("%02x", c:byte()) end)) end
local function cstr(s)
  local z = s:find("\0", 1, true)
  if z then s = s:sub(1, z - 1) end
  return '"' .. s:gsub("[^\32-\126]", function(c) return string.format("\\x%02x", c:byte()) end) .. '"'
end

local function f32(u)
  local sign, e, m = u >= 0x80000000 and -1 or 1, math.floor(u / 0x800000) % 256, u % 0x800000
  if e == 0 then return sign * m * 2 ^ -149 end
  if e == 255 then return m == 0 and sign * math.huge or 0 / 0 end
  return sign * (1 + m / 0x800000) * 2 ^ (e - 127)
end

-- -> number value, display string. No %d/%X: Lua 5.2 on Windows formats them through a 32-bit long.
local function int(s, pos, t)
  local n, v = INT[t][1], 0
  local raw = s:sub(pos + 1, pos + n)
  local hx = "0x" .. hex(raw:reverse()):gsub("^0+(.)", "%1")
  if n == 8 then return nil, hx end
  for i = n, 1, -1 do v = v * 256 + raw:byte(i) end
  if t == "f32" then return nil, string.format("%g", f32(v)) end
  if INT[t][2] and v >= SPAN[n] / 2 then v = v - SPAN[n] end
  local dec = string.format("%.0f", v)
  return v, (v > 9 or v < 0) and dec .. " (" .. hx .. ")" or dec
end

-- annotation fields {{off, type, name}} -> nodes {off, len, label, children, mask}, end offset, problem
function F.decode_ann(p, fields, bo, show_pw)
  local nodes, vals, pos, variable = {}, {}, 0, false
  for _, f in ipairs(fields) do
    local name = f[3]
    if not variable then pos = f[1] end
    local base, dimstr = f[2]:match("^([%w_]+)(.*)$")
    local dims, count = {}, 1
    for d in dimstr:gmatch("%[([%w_]+)%]") do
      local v = tonumber(d)
      if not v then
        variable = true
        v = type(vals[d]) == "number" and vals[d] or math.max(0, #p - pos)
      end
      dims[#dims + 1], count = v, count * v
    end
    local node = {off = bo + pos}
    local st = F.STRUCTS[base]
    if st then
      local n = dims[1] or 1
      node.len = st.size * n
      if pos + node.len > #p then
        return nodes, pos + node.len, string.format("%s: needs %d bytes at %d, payload has %d", name, node.len, pos, #p)
      end
      node.children = {}
      for i = 0, n - 1 do
        local kids = F.decode_ann(p:sub(pos + i * st.size + 1, pos + (i + 1) * st.size), st.f, bo + pos + i * st.size, show_pw)
        if #dims == 0 then node.children = kids
        else node.children[i + 1] = {off = bo + pos + i * st.size, len = st.size, label = string.format("%s[%d]", name, i), children = kids} end
      end
      node.label = #dims == 0 and name or string.format("%s: %d x %s", name, n, base)
    else
      local esz = INT[base] and INT[base][1] or 1
      node.len = esz * count
      if pos + node.len > #p then
        return nodes, pos + node.len, string.format("%s: needs %d bytes at %d, payload has %d", name, node.len, pos, #p)
      end
      local raw, val = p:sub(pos + 1, pos + node.len)
      if base == "char" and #dims > 0 then val = cstr(raw)
      elseif INT[base] and #dims == 0 then
        local v
        v, val = int(raw, 0, base)
        vals[name] = v
        if v and (name:find("error") or name:find("reason")) and F.ERRORS[v] then val = val .. " (" .. F.ERRORS[v] .. ")" end
      elseif INT[base] and base ~= "u8" and base ~= "byte" then
        local t = {}
        for i = 0, count - 1 do local _, s = int(raw, i * esz, base); t[#t + 1] = s end
        val = "[" .. table.concat(t, ", ") .. "]"
      else val = hex(raw) end
      if name:lower():find("password") and not show_pw then val, node.mask = "********", true end
      node.label = name .. ": " .. val
    end
    nodes[#nodes + 1] = node
    pos = pos + node.len
  end
  return nodes, pos
end

-- generated fields {{off, type, size}} -> nodes (first non-overlapping field per offset, labelled "guess")
function F.decode_gen(p, fields)
  local nodes, cov = {}, {}
  for _, f in ipairs(fields) do
    local o, t, n = f[1], f[2], f[3]
    if not cov[o] and o < #p then
      local val
      if t:sub(1, 4) == "char" and (n > 1 or t == "char*") then
        if n == 0 then n = ((p:find("\0", o + 1, true) or #p) - o) end
        n = math.min(n, #p - o)
        val = cstr(p:sub(o + 1, o + n))
      elseif INT[t] and o + INT[t][1] <= #p then
        n = INT[t][1]
        local _, s = int(p, o, t)
        val = s
      else
        n = math.min(n > 0 and n or #p - o, #p - o)
        val = hex(p:sub(o + 1, o + n))
      end
      local free = true
      for i = o, o + n - 1 do if cov[i] then free = false end end
      if free then
        for i = o, o + n - 1 do cov[i] = true end
        nodes[#nodes + 1] = {off = o, len = n, label = string.format("+%d %s (guess): %s", o, t, val)}
      end
    end
  end
  return nodes
end

-- -> {name, source, nodes, issues = {{kind = "unknown"|"size", text}}}
function F.decode(kind, c2s, op, p, show_pw)
  local d = c2s and "c2s" or "s2c"
  local ann, gen = F.ANN[kind][d][op], F.GEN[kind][d][op]
  local desc = ann and ann.name ~= "" and ann.name or nil
  local r = {name = F.NAMES[op] or desc, nodes = {}, issues = {}}
  if desc and desc ~= r.name then r.desc = desc end
  local function issue(k, ...) r.issues[#r.issues + 1] = {kind = k, text = string.format(...)} end
  if c2s and gen then
    for _, n in ipairs(gen.lc) do
      if n ~= #p + 2 then issue("size", "length check: handler requires body length %d, got %d", n, #p + 2) end
    end
  end
  if ann then
    local nodes, stop, prob = F.decode_ann(p, ann.f, 0, show_pw)
    r.nodes, r.source = nodes, "annotation"
    if prob then issue("size", "%s", prob)
    elseif stop ~= #p then issue("size", "payload %d bytes, documented %d", #p, stop) end
  elseif gen and c2s then
    r.nodes, r.source = F.decode_gen(p, F.L[gen.f]), "generated"
  elseif gen then
    local l = gen[#p] or gen.var
    if not l then
      issue("size", "payload %d bytes matches no send site (documented: %s)", #p, gen.doc)
      l = gen.first
    end
    r.nodes, r.source = F.decode_gen(p, F.L[l]), "generated"
  elseif not F.NAMES[op] then
    issue("unknown", "unknown opcode 0x%04X", op)
  end
  return r
end

if not Proto then return F end     -- standalone (self-test): no Wireshark API below this line

-- ---------------------------------------------------------------- Wireshark glue
local proto = Proto("fiesta", "Fiesta Online")
local pf = {
  len = ProtoField.uint16("fiesta.len", "Length (opcode + payload)"),
  opcode = ProtoField.uint16("fiesta.opcode", "Opcode", base.HEX),
  dept = ProtoField.uint8("fiesta.dept", "Department"),
  cmd = ProtoField.uint16("fiesta.cmd", "Command"),
  name = ProtoField.string("fiesta.name", "Name"),
  server = ProtoField.string("fiesta.server", "Server"),
  dir = ProtoField.string("fiesta.dir", "Direction"),
  xor_index = ProtoField.uint16("fiesta.xor_index", "XOR start index"),
  source = ProtoField.string("fiesta.layout", "Layout source"),
  payload = ProtoField.bytes("fiesta.payload", "Payload"),
}
proto.fields = {pf.len, pf.opcode, pf.dept, pf.cmd, pf.name, pf.server, pf.dir, pf.xor_index, pf.source, pf.payload}
local ex = {
  unknown = ProtoExpert.new("fiesta.unknown_opcode", "Unknown opcode", expert.group.UNDECODED, expert.severity.WARN),
  size = ProtoExpert.new("fiesta.size_mismatch", "Payload size differs from the documented layout", expert.group.MALFORMED, expert.severity.WARN),
  noseed = ProtoExpert.new("fiesta.no_seed", "Client packet before the seed (0x0807): cannot decrypt", expert.group.UNDECODED, expert.severity.NOTE),
}
proto.experts = {ex.unknown, ex.size, ex.noseed}
proto.prefs.login_ports = Pref.string("Login server ports", F.PORTS.login, "Comma-separated TCP ports")
proto.prefs.wm_ports = Pref.string("World manager ports", F.PORTS.wm, "Comma-separated TCP ports")
proto.prefs.zone_ports = Pref.string("Zone server ports", F.PORTS.zone, "Comma-separated TCP ports")
proto.prefs.show_password = Pref.bool("Show password", false, "Show the 0x0C5A password instead of ********")

local tcp_port, ports = DissectorTable.get("tcp.port"), {}
local function register()
  for port in pairs(ports) do tcp_port:remove(port, proto) end
  ports = {}
  for _, k in ipairs({"login", "wm", "zone"}) do
    for s in proto.prefs[k .. "_ports"]:gmatch("%d+") do
      ports[tonumber(s)] = k
      tcp_port:add(tonumber(s), proto)
    end
  end
end
proto.prefs_changed = register
register()

-- convs: running XOR index per connection; starts: XOR start index per C->S PDU, computed once on the first pass
local convs, starts = {}, {}
function proto.init() convs, starts = {}, {} end

local function add_nodes(parent, tvb, base, nodes)
  for _, n in ipairs(nodes) do
    if n.len > 0 then
      local it = parent:add(tvb(base + n.off, n.len), n.label)
      if n.children then add_nodes(it, tvb, base, n.children) end
    end
  end
end

local function mask(s, nodes)      -- overwrite masked fields (password) in the decrypted body with '*'
  for _, n in ipairs(nodes) do
    if n.mask then s = s:sub(1, 2 + n.off) .. string.rep("*", n.len) .. s:sub(3 + n.off + n.len) end
    if n.children then s = mask(s, n.children) end
  end
  return s
end

local function set_info(pinfo, s)
  if tostring(pinfo.cols.info):find("Fiesta:", 1, true) then pinfo.cols.info:append(", " .. s)
  else pinfo.cols.info:set("Fiesta: " .. s) end
end

local function dissect_pdu(tvb, pinfo, tree)
  local c2s = ports[pinfo.dst_port] ~= nil
  local kind = c2s and ports[pinfo.dst_port] or ports[pinfo.src_port]
  local total, hl = F.pdu_len(function(i) return tvb(i, 1):uint() end)
  local raw = tvb:raw(hl, total - hl)
  local start
  if c2s then
    local key = pinfo.number .. ":" .. tvb:offset()
    if not pinfo.visited then
      local ck = string.format("%s:%d-%s:%d", tostring(pinfo.dst), pinfo.dst_port, tostring(pinfo.src), pinfo.src_port)
      convs[ck] = convs[ck] or {}
      starts[key] = F.track(convs[ck], true, raw) or false
    end
    start = starts[key]
  elseif not pinfo.visited then
    local ck = string.format("%s:%d-%s:%d", tostring(pinfo.src), pinfo.src_port, tostring(pinfo.dst), pinfo.dst_port)
    convs[ck] = convs[ck] or {}
    F.track(convs[ck], false, raw)
  end

  local dir = c2s and "C->S" or "S->C"
  local t = tree:add(proto, tvb())
  t:add(pf.server, kind):set_generated()
  t:add(pf.dir, dir):set_generated()
  if hl == 1 then t:add(pf.len, tvb(0, 1)) else t:add_le(pf.len, tvb(1, 2)) end
  if #raw < 2 then
    t:add_proto_expert_info(ex.size, "body shorter than an opcode")
    return tvb:len()
  end
  if c2s and not start then
    t:set_text(string.format("Fiesta %s %s (encrypted, %d bytes)", kind, dir, #raw))
    t:add_proto_expert_info(ex.noseed)
    set_info(pinfo, dir .. " encrypted")
    return tvb:len()
  end
  local body, btvb = raw, tvb(hl):tvb()
  if c2s then body = F.decrypt(raw, start) end
  local op = body:byte(1) + 256 * body:byte(2)
  local r = F.decode(kind, c2s, op, body:sub(3), proto.prefs.show_password)
  if c2s then
    btvb = ByteArray.new(hex(mask(body, r.nodes))):tvb("Decrypted")
    t:add(pf.xor_index, start):set_generated()
  end
  local name = r.name or "?"
  t:set_text(string.format("Fiesta %s %s 0x%04X %s%s (%d bytes)", kind, dir, op, name,
                           r.desc and " [" .. r.desc .. "]" or "", #body - 2))
  t:add_le(pf.opcode, btvb(0, 2))
  t:add(pf.dept, btvb(0, 2), math.floor(op / 1024))
  t:add(pf.cmd, btvb(0, 2), op % 1024)
  t:add(pf.name, btvb(0, 2), name)
  if r.source then t:add(pf.source, r.source):set_generated() end
  if #body > 2 then
    local pl = t:add(pf.payload, btvb(2))
    add_nodes(pl, btvb, 2, r.nodes)
  end
  for _, i in ipairs(r.issues) do t:add_proto_expert_info(ex[i.kind], i.text) end
  set_info(pinfo, string.format("%s 0x%04X %s", dir, op, name))
  return tvb:len()
end

local function get_len(tvb, pinfo, offset)
  return (F.pdu_len(function(i) return tvb(offset + i, 1):uint() end))
end

function proto.dissector(tvb, pinfo, tree)
  pinfo.cols.protocol = "Fiesta"
  dissect_tcp_pdus(tvb, tree, 3, get_len, dissect_pdu, true)   -- every PDU is >= 3 bytes (len + opcode)
  return tvb:len()
end
